CREATE TABLE system_dictionary_type(id BIGINT NOT NULL,code VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,name VARCHAR(100) NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE,version BIGINT UNSIGNED NOT NULL DEFAULT 0,PRIMARY KEY(id),UNIQUE KEY uk_system_dictionary_type_code(code));
CREATE TABLE system_dictionary_item(id BIGINT NOT NULL,type_id BIGINT NOT NULL,item_key VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,item_value VARCHAR(500) NOT NULL,sort_order INT NOT NULL DEFAULT 0,enabled BOOLEAN NOT NULL DEFAULT TRUE,version BIGINT UNSIGNED NOT NULL DEFAULT 0,PRIMARY KEY(id),UNIQUE KEY uk_system_dictionary_item(type_id,item_key),CONSTRAINT fk_system_dictionary_item_type FOREIGN KEY(type_id) REFERENCES system_dictionary_type(id) ON DELETE CASCADE);
CREATE TABLE system_setting(setting_key VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,setting_value TEXT NOT NULL,value_type VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,secret BOOLEAN NOT NULL DEFAULT FALSE,description VARCHAR(500) NULL,version BIGINT UNSIGNED NOT NULL DEFAULT 0,updated_by BIGINT NOT NULL,updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),PRIMARY KEY(setting_key));
CREATE TABLE system_feature_flag(flag_key VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,enabled BOOLEAN NOT NULL DEFAULT FALSE,rollout_percent INT UNSIGNED NOT NULL DEFAULT 0,rules_json JSON NULL,version BIGINT UNSIGNED NOT NULL DEFAULT 0,updated_by BIGINT NOT NULL,updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),PRIMARY KEY(flag_key),CONSTRAINT chk_system_feature_rollout CHECK(rollout_percent<=100));
CREATE TABLE system_configuration_audit(id BIGINT NOT NULL,config_type VARCHAR(24) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,config_key VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,old_digest CHAR(64) NULL,new_digest CHAR(64) NOT NULL,operator_user_id BIGINT NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(id),INDEX idx_system_config_audit_key_time(config_type,config_key,created_at));
